// Parses a positive finite number into { mantissa: BigInt, power: number }
// representing mantissa * 10^power without floating-point rounding.
function parseDecimal(w) {
  const match = /^(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/i.exec(String(w));
  if (!match) throw new Error("bad weights");
  const intPart = match[1];
  const fracPart = match[2] || "";
  const exp = match[3] ? Number(match[3]) : 0;
  return {
    mantissa: BigInt(intPart + fracPart),
    power: exp - fracPart.length,
  };
}

// Splits a bill (in agorot, a whole number) between people by weights.
function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => !(w > 0) || !Number.isFinite(w))) {
    throw new Error("bad weights");
  }

  const parsed = weights.map(parseDecimal);
  const minPower = Math.min(...parsed.map((p) => p.power));
  const scaled = parsed.map((p) => p.mantissa * 10n ** BigInt(p.power - minPower));
  const sum = scaled.reduce((a, b) => a + b, 0n);

  const totalBig = BigInt(total);
  const shares = new Array(weights.length);
  const rems = new Array(weights.length);
  let allocated = 0n;

  for (let i = 0; i < scaled.length; i++) {
    const numerator = totalBig * scaled[i];
    const floorShare = numerator / sum;
    shares[i] = Number(floorShare);
    rems[i] = numerator % sum;
    allocated += floorShare;
  }

  const leftover = Number(totalBig - allocated);
  const order = Array.from({ length: weights.length }, (_, i) => i).sort((a, b) => {
    if (rems[b] > rems[a]) return 1;
    if (rems[b] < rems[a]) return -1;
    return a - b;
  });

  for (let k = 0; k < leftover; k++) {
    shares[order[k]] += 1;
  }

  return shares;
}

module.exports = { splitBill };
