// Find free gaps within [dayStart, dayEnd] given busy ranges.
const { parseTime, formatMinutes, parseRange } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen) {
  const start = parseTime(dayStart);
  const end = parseTime(dayEnd);
  if (end <= start) throw new Error("dayEnd must be after dayStart");

  const intervals = [];
  for (const item of busy) {
    const r = parseRange(item);
    const s = Math.max(start, r.start);
    const e = Math.min(end, r.end);
    if (s < e) intervals.push({ start: s, end: e });
  }

  intervals.sort((a, b) => a.start - b.start || a.end - b.end);

  const gaps = [];
  let cursor = start;
  for (const interval of intervals) {
    if (interval.start > cursor && interval.start - cursor >= minLen) {
      gaps.push(`${formatMinutes(cursor)}-${formatMinutes(interval.start)}`);
    }
    if (interval.end > cursor) {
      cursor = interval.end;
    }
  }
  if (end > cursor && end - cursor >= minLen) {
    gaps.push(`${formatMinutes(cursor)}-${formatMinutes(end)}`);
  }

  return gaps;
}

module.exports = { freeSlots };
