// Find free time gaps within a day given busy ranges.
const { parseTime, parseRange, formatMinutes } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen = 0) {
  const start = parseTime(dayStart);
  const end = parseTime(dayEnd);
  if (end <= start) {
    throw new Error("dayEnd must be after dayStart");
  }
  if (!Array.isArray(busy)) {
    throw new Error("busy must be an array");
  }
  if (typeof minLen !== "number" || Number.isNaN(minLen) || minLen < 0) {
    throw new Error("bad minLen: " + minLen);
  }

  const clamped = [];
  for (const item of busy) {
    const range = parseRange(item);
    const cs = Math.max(range.start, start);
    const ce = Math.min(range.end, end);
    if (cs < ce) {
      clamped.push({ start: cs, end: ce });
    }
  }

  clamped.sort((a, b) => a.start - b.start || a.end - b.end);

  const gaps = [];
  let cursor = start;
  for (const interval of clamped) {
    if (interval.start > cursor && interval.start - cursor >= minLen) {
      gaps.push(`${formatMinutes(cursor)}-${formatMinutes(interval.start)}`);
    }
    if (interval.end > cursor) {
      cursor = interval.end;
    }
  }
  if (end > cursor && end - cursor >= minLen) {
    gaps.push(`${formatMinutes(cursor)}-${formatMinutes(end)}`);
  }

  return gaps;
}

module.exports = { freeSlots };
